class IntroAboutText extends StatelessWidget {
  const IntroAboutText({super.key, required this.isDesktop});

  final bool isDesktop;

  // Lines break between the short sentences ("Your privacy. Your keys." /
  // "Your PIVX."), never inside one.
  static String _breakBetweenSentences(String text) => text
      .split(". ")
      .map((sentence) => sentence.replaceAll(" ", "\u00a0"))
      .join(". ");

  @override
  Widget build(BuildContext context) {
    return Text(
      _breakBetweenSentences(AppConfig.shortDescriptionText),
      textAlign: TextAlign.center,
      style: !isDesktop
          ? STextStyles.subtitle(context)
          : STextStyles.subtitle(context).copyWith(fontSize: 24),
    );
  }
}

/// "By using the app you agree to the Terms of service and Privacy
/// policy", with whichever of the two links the app config sets (nothing
/// when neither).
class PrivacyAndTOSText extends StatelessWidget {
  const PrivacyAndTOSText({
    super.key,
    required this.isDesktop,
    this.fontSize,
    this.textColor,
  });

  final bool isDesktop;
  final double? fontSize;
  final Color? textColor;

  @override
  Widget build(BuildContext context) {
    final size = fontSize ?? (isDesktop ? 18.0 : 12.0);
    final links = [
      if (AppConfig.termsUrl.isNotEmpty)
        (l10n.introTermsLink, AppConfig.termsUrl),
      if (AppConfig.privacyUrl.isNotEmpty)
        (l10n.introPrivacyLink, AppConfig.privacyUrl),
    ];
    if (links.isEmpty) return const SizedBox.shrink();
    final textStyle = STextStyles.label(context)
        .copyWith(fontSize: size, color: textColor);
    // The sentence with \u0000 and \u0001 where the links go.
    final sentence = links.length == 1
        ? l10n.introAgreeOne(AppConfig.appName, "\u0000")
        : l10n.introAgreeTwo(AppConfig.appName, "\u0000", "\u0001");
    final children = <InlineSpan>[];
    var at = 0;
    for (final m in RegExp("[\u0000\u0001]").allMatches(sentence)) {
      final link = links[sentence.codeUnitAt(m.start)];
      children.addAll([
        TextSpan(text: sentence.substring(at, m.start)),
        TextSpan(
          text: link.$1,
          style: STextStyles.richLink(context).copyWith(fontSize: size),
          recognizer: TapGestureRecognizer()
            ..onTap = () => launchUrl(
              Uri.parse(link.$2),
              mode: LaunchMode.externalApplication,
            ),
        ),
      ]);
      at = m.end;
    }
    children.add(TextSpan(text: sentence.substring(at)));
    return RichText(
      textAlign: TextAlign.center,
      text: TextSpan(style: textStyle, children: children),
    );
  }
}

class GetStartedButton extends StatelessWidget {
  const GetStartedButton({super.key, required this.isDesktop});

  final bool isDesktop;

  @override
  Widget build(BuildContext context) {
    return !isDesktop
        ? TextButton(
            style: Theme.of(context)
                .extension<StackColors>()!
                .getPrimaryEnabledButtonStyle(context),
            onPressed: () {
              Prefs.instance.externalCalls = true;
              Navigator.of(context)
                  .pushNamed(StackPrivacyCalls.routeName, arguments: false);
            },
            child: Text(
              l10n.introGetStarted,
              style: STextStyles.button(context),
            ),
          )
        : SizedBox(
            width: double.infinity,
            height: 70,
            child: TextButton(
              style: Theme.of(context)
                  .extension<StackColors>()!
                  .getPrimaryEnabledButtonStyle(context),
              onPressed: () {
                // As on mobile: Easy Crypto until chosen otherwise.
                Prefs.instance.externalCalls = true;
                Navigator.of(context)
                    .pushNamed(StackPrivacyCalls.routeName, arguments: false);
              },
              child: Text(
                l10n.introCreateNew(AppConfig.prefix),
                style: STextStyles.button(context).copyWith(fontSize: 20),
              ),
            ),
          );
  }
}
